 void refresh(){visible.clear();if(has(data,"rows"))for(Object row:(Iterable<?>)c(get(data,"rows"),"getAsJsonArray"))if(bool(row,"injured"))visible.add(row);visible.sort(Comparator.comparingInt(r->Arrays.asList(PARTS).indexOf(str(r,"part"))));if(visible.stream().noneMatch(r->integer(r,"index")==selected))selected=visible.isEmpty()?-1:integer(visible.getFirst(),"index");if(treat!=null){boolean down=str(data,"stage").equals("down");treat.visible=down||!visible.isEmpty();treat.active=down||!visible.isEmpty()&&str(data,"stage").equals("examined");treat.setMessage(tr(down?"revive":"treat"));}}
 int mode(){if(npc)return 4;Object row=visible.stream().filter(r->integer(r,"index")==selected).findFirst().orElse(null);if(row==null)return 4;int modes=integer(row,"modes");Object player=Minecraft.getInstance().player,inv=c(player,"getInventory");for(int mode:new int[]{3,2,1,4})if((modes&(1<<mode))!=0)for(int i=0;i<((Number)c(inv,"getContainerSize")).intValue();i++)if(Boolean.TRUE.equals(c(R.type("dev.zomboid.integration.care.Medical"),"item",c(inv,"getItem",i),mode)))return mode;for(int mode:new int[]{3,2,1,4})if((modes&(1<<mode))!=0)return mode;return 4;}
 public void renderBackground(GuiGraphics g,int x,int y,float p){}protected void renderBlurredBackground(float p){}
 public void render(GuiGraphics g,int mx,int my,float p){int x=left(),y=top(),w=panel();g.fill(x-1,y-3,x+w+1,y+230,0xff7f8878);g.fill(x,y-2,x+w,y+229,0xff111811);super.render(g,mx,my,p);g.drawCenteredString(font,tr("patient",str(data,"patient")),width/2,y+5,0xffe0d5ae);String stage=str(data,"stage");if(stage.equals("offer"))return;if(stage.equals("down")){g.drawCenteredString(font,tr("down"),width/2,y+65,0xffdf9191);return;}
  drawBody(g,x+12,y+40,90,150);int rx=x+112,cw=Math.max(44,(w-122)/2),h=37;for(int i=0;i<visible.size();i++){Object row=visible.get(i);int px=rx+i%2*cw,py=y+37+i/2*h;g.fill(px,py,px+cw-4,py+h-3,integer(row,"index")==selected?0xff343b2e:0xff1c251c);Object label=tr("part."+str(row,"part").toLowerCase(Locale.ROOT));int yy=py+3;for(Object line:(Iterable<?>)c(font,"split",label,Math.max(30,cw-10))){c(g,"drawString",font,line,px+3,yy,0xffdbd1b4,false);yy+=9;}Object description=npc?tr("injury"):Component.literal(str(row,"details"));for(Object line:(Iterable<?>)c(font,"split",description,Math.max(30,cw-10))){if(yy>py+h-10)break;c(g,"drawString",font,line,px+3,yy,0xffd88f8f,false);yy+=9;}}
  if(visible.isEmpty())g.drawCenteredString(font,tr("healthy"),x+w/2+35,y+78,0xffa9c798);if(!stage.equals("work")){Object note=npc?tr("hold_bandage"):Component.literal(str(data,"message"));int ny=y+183;for(Object line:(Iterable<?>)c(font,"split",note,w-18)){c(g,"drawCenteredString",font,line,width/2,ny,0xffb7c5a3);ny+=10;if(ny>=y+202)break;}}int progress=integer(data,"progress");if(stage.equals("work")){g.drawCenteredString(font,tr("progress",progress),width/2,y+183,0xffe1d3aa);g.fill(x+114,y+195,x+w-12,y+200,0xff303a30);g.fill(x+114,y+195,x+114+(w-126)*Math.max(0,Math.min(100,progress))/100,y+200,0xff94bc72);}}
 void drawBody(GuiGraphics g,int x,int y,int w,int h){int[][] rect={{34,0,23,23},{27,27,37,51},{13,28,11,53},{67,28,11,53},{29,81,16,50},{48,81,16,50},{25,134,20,11},{48,134,20,11}};for(int i=0;i<rect.length;i++){final String part=PARTS[i];boolean injured=visible.stream().anyMatch(r->str(r,"part").equals(part));int[] q=rect[i];int px=x+q[0]*w/90,py=y+q[1]*h/150,pw=q[2]*w/90,ph=q[3]*h/150;g.fill(px,py,px+pw,py+ph,injured?0xffdf7777:0xff77816d);g.fill(px+1,py+1,px+pw-1,py+ph-1,injured?0xff402a25:0xff1c241c);}}
 public boolean mouseClicked(double mx,double my,int button){if(button==0||button==1){int rx=left()+112,cw=Math.max(44,(panel()-122)/2),dy=(int)my-top()-37;if(mx>=rx&&mx<rx+2*cw&&dy>=0&&dy<148){int i=dy/37*2+(mx>=rx+cw?1:0);if(i<visible.size()){selected=integer(visible.get(i),"index");if(button==1&&treat.active)send(3,mode());return true;}}}return super.mouseClicked(mx,my,button);}
 public void onClose(){send(0,0);super.onClose();}public boolean isPauseScreen(){return false;}
